/* ===== Phase 11: Medium problems (part 1) ===== */
P(11,{key:'Design WhatsApp',short:'WhatsApp',
  lead:'Design a chat app: one-to-one and group messages delivered in real time, sent/delivered/read receipts, offline delivery, and media, for hundreds of millions of daily users.',
  more:['Clients hold persistent WebSocket (or MQTT) connections to gateway servers. A connection registry maps each user to their gateway. Sending a message: store it durably first (a write-optimised store partitioned by conversation), then route it to the recipient\'s gateway through pub/sub, or queue it for offline delivery with a push notification. Message ids per conversation give ordering; clients sync from their last seen id after reconnecting. Groups fan out to members; media goes to object storage with the message carrying a link.'],
  clarify:[['Group size limit?','Assume up to 1,000 members.'],['Message history kept on server?','Assume yes until delivered, with optional cloud history.'],['End-to-end encryption?','Mention it: the server routes ciphertext it cannot read.'],['Scale?','Assume 500 million daily users, 40 messages each.']],
  est:{dau:500e6,writes:40,ratio:1.5,size:200,years:1,peak:3,wlabel:'messages',rlabel:'deliveries',unit:'message'},
  build:B(['WebSocket gateways with a user-to-gateway registry | Real-time two-way delivery and routing.','Message store partitioned by conversation id (wide-column) | High write volume, ordered reads per chat.','Pub/sub between chat service and gateways | Route messages to the server holding the recipient.','Offline queue plus push notifications (APNs/FCM) | Deliver when the user returns.','Object storage and CDN for media | Keep large blobs out of the message path.','Per-conversation sequence ids and client sync from last id | Ordering and gap-free recovery.'],['Polling every second from every client | Wasteful at this scale and slow.','Single relational database for all messages | Write volume and size exceed one node.','Storing messages only in gateway memory | Lost on crash or reconnect.']),
  takeaway:'Persistent connections plus a registry for routing, store-then-deliver for reliability, per-conversation ordering, offline sync from the last seen id, and media out of band.',
  pre:['WebSockets','Long Polling vs WebSockets','Database Sharding','Message Queues'],
  quiz:[{q:'Why store a message before attempting delivery?',o:['It is faster','So it is not lost if the recipient is offline or a server crashes','Because WebSockets require it'],a:1,why:'Durable storage first makes delivery retryable.',hint:'What if delivery fails?'},
        {q:'How does the system know which server holds a user\'s connection?',o:['It broadcasts to all servers','A connection registry maps user to gateway','DNS'],a:1,why:'A fast lookup (cache or KV store) updated on connect and disconnect.',hint:'A lookup table.'}],
  terms:[['Gateway','Server holding client connections.'],['Receipt','Acknowledgement that a message was delivered or read.'],['Fan-out','Delivering one message to many recipients.']],
  deep:[{h:'Send and receive flow',ul:['Client sends with a client-generated id (dedup on retry).','Chat service assigns a sequence number, stores, acknowledges "sent".','Lookup recipient gateway; publish; gateway pushes; client acks "delivered".','Read receipts as small messages back to the sender.']},
   {h:'Offline and reconnect',ul:['Undelivered messages remain in an inbox per user or are synced by sequence.','Push notification wakes the app.','On reconnect, client requests messages after its last id per conversation.']},
   {h:'Groups',ul:['Store once per group; fan out delivery to online members.','Large groups: fan-out workers; avoid per-message writes per member.','Membership changes and ordering within the group.']},
   {h:'Presence, media, encryption',ul:['Presence via heartbeats; publish to contacts lazily.','Media uploaded to object storage via pre-signed URLs.','End-to-end encryption (Signal protocol): server stores ciphertext; key exchange per device.']}],
  iq:[{q:'Design one-to-one messaging with delivery receipts.',lvl:'Mid',cover:['Connections, registry, store, delivery, acks.','Offline handling.','Data model for messages.'],pitfalls:['No offline path.']},
   {q:'How do you guarantee ordering and no duplicates when clients reconnect often?',cover:['Sequence ids per conversation from the server.','Client message ids for dedup on retries.','Sync from last acknowledged sequence.'],pitfalls:['Relying on timestamps from devices.']},
   {q:'Scale WhatsApp to 2 billion users across regions with end-to-end encryption.',lvl:'Staff+',cover:['Regional gateways; home region per user; cross-region routing.','Storage partitioned by conversation; retention policies.','Multi-device key management.','Capacity for reconnect storms; abuse handling without reading content.'],pitfalls:['Assuming the server can read messages for features.']}]});

P(11,{key:'Design Spotify',short:'Spotify',
  lead:'Design a music streaming service: search a catalogue of 100 million tracks, stream audio with almost no start delay, keep playlists in sync across devices, and recommend music.',
  more:['Audio files are encoded at several bitrates and stored in object storage, then served through CDNs in small chunks so playback starts fast and adapts to network quality. Metadata (tracks, albums, artists, playlists) lives in databases and a search index. Listening events stream into a data pipeline that powers royalties, charts and recommendations. Popular tracks are always in the CDN; the long tail may be fetched from origin, so prefetching the next track hides latency.'],
  clarify:[['Offline downloads?','Yes, with DRM.'],['Scale?','Assume 200 million daily users streaming 1 hour each.'],['Recommendations in scope?','Outline only.'],['Free tier with ads?','Mention, not deep.']],
  est:{dau:200e6,writes:15,ratio:1,size:4e6,years:0,peak:3,wlabel:'song plays',rlabel:'audio file fetches',unit:'audio file'},
  build:B(['Object storage with multiple bitrates per track | Durable audio storage.','CDN serving audio chunks | Low start latency and offload huge bandwidth.','Metadata DB and search index | Browse and search the catalogue.','Playlist service with sync across devices | User data must follow the user.','Event pipeline for plays (Kafka to warehouse) | Royalties, charts, recommendations.','Client prefetch of the next track | Hide fetch latency between songs.'],['Streaming every play from origin servers | Bandwidth and latency would not scale.','Strongly consistent global transactions for play counts | Counts can be eventually consistent.','One huge relational table for listening history queried online | Use the pipeline and warehouse.']),
  takeaway:'Serve audio as chunks through CDNs with prefetching, keep metadata and playlists in databases with search on top, and stream listening events into a pipeline for royalties and recommendations.',
  pre:['Content Delivery Network (CDN)','Batch vs Stream Processing'],
  quiz:[{q:'How can playback start almost instantly?',o:['Download the whole file first','Fetch the first chunk from a nearby CDN at a low bitrate and prefetch the next track','Use a bigger server'],a:1,why:'Small chunks and edge caching cut start latency.',hint:'First chunk, nearby.'},
        {q:'Where should play counts for royalties be computed?',o:['In the playback request path','From a durable event stream processed asynchronously','On the client'],a:1,why:'Events are durable and can be reprocessed; playback stays fast.',hint:'Do not slow playback.'}],
  terms:[['Adaptive bitrate','Switching quality based on network conditions.'],['DRM','Encryption controlling playback of downloaded content.'],['Long tail','Many rarely played tracks.']],
  deep:[{h:'Audio delivery',ul:['Encode Ogg/AAC at several bitrates; split into chunks.','CDN with long TTLs; signed URLs.','Prefetch next track; local cache on device.']},
   {h:'Catalogue and search',ul:['Metadata service backed by a relational or document store.','Search index (Elasticsearch) with typo tolerance.','Ingestion pipeline from labels.']},
   {h:'Playlists and library',ul:['Playlist service partitioned by user; collaborative playlists with versioning.','Sync via change feeds to devices.','Offline downloads with license checks.']},
   {h:'Events and recommendations',ul:['Client sends play events; batched.','Stream processing for real-time charts.','Batch jobs for collaborative filtering and Discover-style playlists.']}],
  iq:[{q:'Design the flow from pressing play to hearing audio.',lvl:'Mid',cover:['Metadata lookup, licence check, CDN URL.','Chunked fetch, adaptive bitrate, buffering.','Event logging.'],pitfalls:['Serving files from application servers.']},
   {q:'How do you keep playlists consistent across a phone, laptop and speaker?',cover:['Server as source of truth with versions.','Change notifications or sync on open.','Conflict handling for offline edits.'],pitfalls:['Last-write-wins dropping items silently.']},
   {q:'Royalties must be exact per play across 200 million users. Design the pipeline.',lvl:'Staff+',cover:['Durable play events with ids; dedup.','Batch reconciliation and audit trail.','Late and offline plays handled; fraud filtering.','Reprocessing capability.'],pitfalls:['Counting in an in-memory cache.']}]});

P(11,{key:'Design Instagram',short:'Instagram',
  lead:'Design a photo-sharing social network: upload photos, follow people, see a feed of followed users\' posts, like and comment, at hundreds of millions of daily users.',
  more:['Uploads go directly to object storage with pre-signed URLs; a pipeline creates resized versions served via CDN. Post metadata, follows, likes and comments live in partitioned databases. The feed is the core deep dive: fan-out on write into per-user feed caches for most authors, pull for celebrities, merged and ranked at read time. Real interview reports also show interviewers asking for product flows and the data schema.'],
  clarify:[['Features in scope?','Upload, follow, feed, likes, comments. Stories and DMs out of scope.'],['Scale?','Assume 500 million daily users, 100 million photos a day.'],['Feed ordering?','Ranked, not purely chronological.'],['Latency?','Feed under 300 ms.']],
  est:{dau:500e6,writes:0.2,ratio:300,size:2e6,years:5,peak:3,wlabel:'photo uploads',rlabel:'photo views',unit:'photo (all sizes)'},
  build:B(['Pre-signed uploads to object storage | Clients send large files directly, not through app servers.','Image processing workers (resize, thumbnails) via a queue | Async heavy work.','CDN for images | Most bandwidth served at the edge.','Partitioned stores for posts, follows, likes | Scale metadata.','Feed service: fan-out on write for most, pull for celebrities | Fast feed reads without write storms.','Feed cache per user (Redis) | Serve feeds in milliseconds.'],['Images stored as blobs in the relational database | Bloats the database; use object storage.','Fan-out on write for accounts with 300 million followers | Write storm.','Synchronous image resizing in the upload request | Slow uploads and fragile.']),
  takeaway:'Object storage plus CDN for media, async processing, partitioned metadata, and a hybrid fan-out feed cached per user and ranked on read.',
  pre:['Push vs Pull Architecture','Content Delivery Network (CDN)','Database Sharding'],
  quiz:[{q:'Why use pre-signed URLs for uploads?',o:['They compress images','Clients upload straight to object storage, keeping large transfers off app servers','They are required for HTTPS'],a:1,why:'App servers only authorise; storage handles the bytes.',hint:'Who carries the bytes?'},
        {q:'How do celebrity posts reach followers\' feeds?',o:['Pushed into every follower\'s feed','Pulled and merged at read time','Emailed'],a:1,why:'Avoids millions of writes per celebrity post.',hint:'Hybrid fan-out.'}],
  terms:[['Pre-signed URL','Time-limited URL granting upload or download rights.'],['Feed cache','Precomputed list of post ids per user.'],['Ranking','Ordering feed items by predicted interest.']],
  deep:[{h:'Data model',ul:['users(id, ...), posts(id, author_id, media keys, caption, created_at).','follows(follower_id, followee_id) with both directions indexed.','likes(post_id, user_id), comments(post_id, id, ...) partitioned by post.','Counters kept separately and updated asynchronously.']},
   {h:'Upload path',ul:['Request upload URL; upload; create post record.','Queue processing: variants, moderation, metadata.','Publish PostCreated for fan-out.']},
   {h:'Feed',ul:['Fan-out workers push post ids into followers\' feed caches (cap length).','Celebrity posts fetched at read time and merged.','Ranking service scores candidates.','Pagination with cursors.']},
   {h:'Scale and reliability',ul:['Shard by user id or post id.','Hot posts: cache likes and comments; counters sharded.','CDN and multiple image sizes per device.']}],
  iq:[{q:'Design photo upload and viewing end to end.',lvl:'Mid',cover:['Pre-signed upload, processing queue, variants.','Metadata storage, CDN serving.','Failure handling for partial uploads.'],pitfalls:['Images in the database.']},
   {q:'Design the home feed with ranking and explain the fan-out trade-offs.',cover:['Hybrid fan-out and feed caches.','Candidate generation and ranking.','Inactive users: compute on demand.','Cost and latency numbers.'],pitfalls:['Pure pull for everyone at this scale.']},
   {q:'A celebrity with 300 million followers posts and the like counter becomes a hot key. Fix it.',lvl:'Staff+',cover:['Sharded counters aggregated periodically.','Approximate counts displayed; exact counts batch-computed.','Write buffering; rate-limited fan-out.','Isolation so one post does not hurt others.'],pitfalls:['Incrementing a single row per like.']}]});

P(11,{key:'Design Notification Service',short:'Notifications',
  lead:'Design a service that other teams call to send notifications by push, SMS and email: respecting user preferences, retrying failures, and delivering huge bursts such as alerting 1 million users for a flash sale (an actual reported Meta E5 prompt).',
  more:['Producers send a request to an API that validates it and writes it to a queue. Workers expand targets (one request may mean a million users), apply preferences, rate limits and deduplication, render templates, and hand off to channel-specific senders that call APNs, FCM, SMS gateways and email providers. Each provider has its own rate limits and failure modes, so senders retry with backoff and dead-letter what keeps failing. Priorities keep a password-reset code from waiting behind a marketing blast.'],
  clarify:[['Channels?','Push, SMS, email; in-app optional.'],['Scale and bursts?','Assume 100 million notifications a day, bursts of 1 million in minutes.'],['Delivery guarantees?','At least once, with deduplication; transactional messages prioritised.'],['User preferences?','Opt-outs per channel and type, quiet hours.']],
  est:{dau:100e6,writes:1,ratio:1,size:1000,years:1,peak:10,wlabel:'notifications',rlabel:'provider calls',unit:'notification record'},
  build:B(['Notification API with idempotency keys | Producers retry safely.','Queues per priority and channel | Absorb bursts and keep urgent messages fast.','Fan-out workers expanding audiences in batches | One campaign to millions of users.','Preference and rate-limit service | Respect opt-outs and avoid spamming.','Channel senders with provider-specific retries and DLQs | Each provider fails differently.','Delivery tracking store and webhooks from providers | Status and analytics.'],['Sending synchronously inside the caller\'s request | Callers would wait on providers and fail with them.','One queue shared by OTP codes and marketing | Urgent messages stuck behind bulk.','No deduplication | Users receive the same message several times.']),
  takeaway:'Accept requests into queues, expand audiences in workers, apply preferences and limits, send through per-channel workers with retries, and separate priorities.',
  pre:['Message Queues','Rate limiting','Idempotency'],
  quiz:[{q:'Why separate queues by priority?',o:['To save money','So a one-time passcode is not delayed behind a million marketing messages','Queues cannot be large'],a:1,why:'Head-of-line blocking hurts urgent messages.',hint:'Which message matters most right now?'},
        {q:'A provider returns errors for 5 minutes. What should senders do?',o:['Drop messages','Retry with backoff, open a circuit breaker, and fall back to another provider or channel if allowed','Retry instantly in a loop'],a:1,why:'Avoid hammering the provider while still delivering eventually.',hint:'Resilience patterns.'}],
  terms:[['APNs / FCM','Apple and Google push notification services.'],['Template','Message text with placeholders.'],['Quiet hours','Times when non-urgent notifications are held.']],
  deep:[{h:'Flow',ul:['Producer calls API (type, audience, template, idempotency key).','Store request; enqueue.','Fan-out: resolve audience in pages; enqueue per user and channel.','Sender: render, check preferences and limits, call provider, record status.']},
   {h:'Burst handling',ul:['1 million users in 5 minutes is about 3,300 per second; provider limits may be lower.','Scale workers horizontally; respect provider quotas with token buckets.','Spread non-urgent campaigns over time.']},
   {h:'Reliability',ul:['At-least-once with dedup by (notification id, user, channel).','DLQs with replay; alerts on failure rates.','Provider failover (multiple SMS vendors).']},
   {h:'User experience',ul:['Preferences and unsubscribe links.','Frequency caps per user.','Time zone aware scheduling and quiet hours.']}],
  iq:[{q:'Design a notification service for push and email.',lvl:'Mid',cover:['API, queue, workers, providers.','Templates and preferences.','Retries and status tracking.'],pitfalls:['Calling providers synchronously from the API.']},
   {q:'Send a flash sale alert to 1 million users within 5 minutes without hurting other notifications.',cover:['Throughput math; provider quotas.','Separate bulk priority queue; fan-out in batches.','Dedup, preferences, frequency caps.','Monitoring progress.'],pitfalls:['Ignoring provider rate limits.']},
   {q:'Make the service multi-tenant for 200 internal teams with fairness and cost controls.',lvl:'Staff+',cover:['Per-tenant quotas and priorities; weighted fair queuing.','Cost attribution per tenant and channel.','Template governance; abuse detection.','Self-service onboarding and SLOs.'],pitfalls:['One noisy team starving others.']}]});

P(11,{key:'Design Distributed Job Scheduler',short:'Job Scheduler',
  lead:'Design a system that runs jobs at scheduled times or intervals (like distributed cron), at large scale, with retries, and optionally with dependencies between jobs. Amazon has asked this with dependent jobs for SDE-2 (June 2026 report).',
  more:['Job definitions (schedule, payload, retry policy, dependencies) live in a database. A scheduler finds due jobs (indexed by next run time), creates a run record, and puts it on a queue; workers pick runs, execute, heartbeat and report results. Scheduler leadership needs a lease or partitioning by job id so jobs are not dispatched twice; workers must still be idempotent because a run can be retried after a worker dies. Dependencies form a DAG: a run is released only when all parents succeed.'],
  clarify:[['One-off and recurring jobs?','Both, cron syntax.'],['Scale?','Assume 10 million jobs per day; jobs run seconds to hours.'],['Exactly once?','At least once with idempotency keys; no double runs in normal operation.'],['Dependencies?','Yes, DAGs of jobs.']],
  est:{dau:10e6,writes:1,ratio:3,size:2000,years:1,peak:5,wlabel:'job runs',rlabel:'status reads',unit:'run record'},
  build:B(['Job store with an index on next run time | Find due jobs efficiently.','Scheduler partitions with leases (or leader per partition) | Dispatch each due job once.','Queue of runs for workers | Decouple dispatch from execution and absorb bursts.','Workers with heartbeats and visibility timeouts | Detect dead workers and retry.','DAG dependency tracker | Release runs when parents succeed.','Run history and alerting | Visibility for owners.'],['Cron on every server | Duplicate runs and no visibility.','Polling the entire job table every second | Expensive at millions of jobs.','A scheduler without idempotency | Retries cause double effects.']),
  takeaway:'Store jobs indexed by next run time, dispatch from partitioned schedulers with leases into a queue, run on workers with heartbeats and retries, make runs idempotent, and gate DAG children on parents.',
  pre:['Distributed Locking','Message Queues','HeartBeats'],
  quiz:[{q:'How do you avoid two scheduler instances dispatching the same job?',o:['Hope','Partition jobs among schedulers with leases, or claim runs with a conditional update','Use more workers'],a:1,why:'Ownership is explicit and only one instance claims each run.',hint:'Ownership.'},
        {q:'A worker dies mid-job. How is the job retried?',o:['It is lost','Its lease or heartbeat expires, the run becomes visible again, and another worker retries it','The scheduler restarts'],a:1,why:'Visibility timeouts and heartbeats detect failure.',hint:'Silence means failure.'}],
  terms:[['DAG','Directed acyclic graph of dependencies.'],['Run','One execution of a job.'],['Misfire','A scheduled time missed because the system was down.']],
  deep:[{h:'Data model',ul:['jobs(id, owner, schedule, payload, retry policy, next_run_at, partition).','runs(id, job_id, scheduled_at, status, attempt, worker, started, finished).','dependencies(parent_job, child_job) or DAG definitions.']},
   {h:'Dispatch',ul:['Each scheduler owns partitions; polls due jobs with SELECT ... FOR UPDATE SKIP LOCKED or a time-bucketed index.','Creates a run, enqueues, advances next_run_at in one transaction.','Misfire policy after downtime: run once, skip, or catch up.']},
   {h:'Execution',ul:['Workers pull runs; heartbeat; extend visibility.','Retries with backoff; max attempts; DLQ.','Timeouts per job; cancellation.']},
   {h:'Dependencies and scale',ul:['On success, decrement counters on children; release when all parents complete.','Failures propagate as blocked children.','Time-bucketed wheels for very large numbers of scheduled jobs.']}],
  iq:[{q:'Design a distributed cron that runs each job once at its scheduled time.',lvl:'Mid',cover:['Job store, scheduler, queue, workers.','Leader or partition ownership.','Retries and visibility.'],pitfalls:['Cron on every server.']},
   {q:'Add support for job dependencies (DAGs) and explain failure handling.',cover:['DAG model and counters.','Release children on parent success; blocked on failure.','Retries, manual reruns of a node and its descendants.'],pitfalls:['Checking parents by polling every second.']},
   {q:'Scale to 1 billion scheduled jobs (for example, per-user reminders) firing at peaks of 1 million per minute.',lvl:'Staff+',cover:['Time-bucketed storage and partitioning by time and id.','Hierarchical timing wheels; pre-load upcoming buckets.','Queue throughput and worker autoscaling; downstream rate limits.','Jitter to smooth peaks; observability.'],pitfalls:['A single table scanned by one scheduler.']}]});

P(11,{key:'Design Tinder',short:'Tinder',
  lead:'Design a dating app: build profiles, show nearby candidates to swipe on, record likes and passes, detect mutual likes as matches, and let matches chat.',
  more:['The recommendation path is the core: candidates near the user (geospatial index such as geohash or S2 cells), filtered by preferences and already-swiped profiles, ranked, and precomputed into a queue per user so swipes feel instant. Swipes are a very high write volume; a match is detected when a like finds the reverse like. A Bloom filter or bitmap per user can cheaply exclude profiles already seen.'],
  clarify:[['Location radius and preferences?','Distance, age range, gender preferences.'],['Scale?','Assume 50 million daily users, 100 swipes each.'],['Real-time match notifications?','Yes.'],['Chat in scope?','Briefly; reuse a chat design.']],
  est:{dau:50e6,writes:100,ratio:0.1,size:100,years:1,peak:3,wlabel:'swipes',rlabel:'match checks',unit:'swipe record'},
  build:B(['Geospatial index of active users (geohash/S2 cells) | Find nearby candidates fast.','Candidate queue precomputed per user | Instant card loading.','Swipe store partitioned by user | Handle billions of writes.','Match detection on like (check reverse like) | Create matches immediately.','Seen-profile filter (Bloom filter or bitmap) | Avoid showing the same person twice.','Notifications and chat for matches | Engagement after matching.'],['Scanning all users by distance per request | Too slow.','A single SQL table of swipes with joins per card | Too much load.','Exact global ranking recalculated on every swipe | Precompute instead.']),
  takeaway:'Geospatial candidate search with filters, precomputed per-user queues, partitioned swipe storage, reverse-like checks for matches, and cheap seen-filters.',
  pre:['Bloom Filters','Database Sharding','Caching 101'],
  quiz:[{q:'How do you find people within 10 km quickly?',o:['Compute distance to every user','Index users by geohash or S2 cells and search the nearby cells','Sort by user id'],a:1,why:'Spatial indexes reduce the search to a few cells.',hint:'Grid cells.'},
        {q:'How is a match detected?',o:['A nightly job','When A likes B, check whether B already liked A','The client decides'],a:1,why:'A point lookup on the reverse edge.',hint:'Two directions.'}],
  terms:[['Geohash','String encoding of a location cell; shared prefixes mean nearby.'],['S2 cell','Google\'s hierarchical sphere cells.'],['Candidate queue','Precomputed list of profiles to show.']],
  deep:[{h:'Data',ul:['profiles(user_id, prefs, photos, location cell).','swipes(swiper_id, swipee_id, type, ts) partitioned by swiper.','matches(user_a, user_b, created_at).']},
   {h:'Recommendations',ul:['Background job fills a queue per user from nearby cells.','Filters: preferences, blocked, seen.','Ranking by activity and compatibility signals.']},
   {h:'Swipes and matches',ul:['Write swipe; if like, check reverse like (partition by swipee too, or cache likes received).','Create match; notify both.','Rate limits to deter bots.']},
   {h:'Location updates',ul:['Update cell on significant movement only.','Expire inactive users from the index.','Privacy: show approximate distance only.']}],
  iq:[{q:'Design the swipe and match flow.',lvl:'Mid',cover:['Swipe storage, reverse lookup, match creation.','Notifications.','Data model.'],pitfalls:['Checking matches in a batch job.']},
   {q:'Design the candidate recommendation pipeline.',cover:['Geo index, filters, ranking.','Precomputed queues with refresh.','Seen filters and their false positives.'],pitfalls:['Real-time scan per card.']},
   {q:'Swipe volume doubles in a city after a marketing campaign. What breaks first and how do you plan?',lvl:'Staff+',cover:['Hot geo cells; candidate generation load.','Swipe write throughput per partition.','Capacity by region; cell splitting; caches.','Load tests and gradual rollout.'],pitfalls:['Assuming uniform load across regions.']}]});

P(11,{key:'Design Facebook',short:'Facebook',
  lead:'Design the core of Facebook: profiles, friendships, posts, the news feed, likes and comments, at billions of users. The social graph and the feed are the centre of the design.',
  more:['The social graph (users, friendships, likes, group memberships) is huge and read-heavy; Facebook stores it in a graph-aware cache over sharded MySQL (TAO). The news feed collects candidate posts from friends, pages and groups, ranks them with machine learning, and serves them with caches. Fan-out strategies, cache consistency for the graph, and privacy checks on every item are the deep dives.'],
  clarify:[['Which features?','Profiles, friends, posts, feed, likes, comments.'],['Scale?','Assume 2 billion daily users.'],['Feed ranking?','Ranked by relevance.'],['Privacy settings?','Each post has an audience that must be enforced.']],
  est:{dau:2e9,writes:1,ratio:100,size:1000,years:5,peak:3,wlabel:'posts',rlabel:'feed item reads',unit:'post'},
  build:B(['Sharded storage for users, posts and edges | Data far beyond one database.','Graph cache layer (TAO-like) for objects and associations | Fast, consistent-enough reads of the graph.','Feed service: candidate generation plus ML ranking | Relevant feeds.','Fan-out and feed caches | Fast reads.','Privacy check on every item | Respect audiences.','Media in object storage and CDN | Photos and videos.'],['One relational database with joins per feed load | Impossible at this scale.','Pure chronological pull from 500 friends on each load without caches | Too slow.','Ignoring privacy filtering in caches | Leaks content.']),
  takeaway:'A sharded store with a graph cache, a feed built from candidates and ranked by ML, aggressive caching, and privacy enforced on every item.',
  pre:['Design Instagram','Push vs Pull Architecture','Distributed Caching'],
  quiz:[{q:'What is the main role of a graph cache like TAO?',o:['Store images','Serve objects and associations (friends, likes) at very high read rates with a cache in front of sharded databases','Rank the feed'],a:1,why:'The graph is read constantly; caching associations is essential.',hint:'Edges between objects.'},
        {q:'Why check privacy when serving each feed item?',o:['For speed','Because audiences can change and caches may hold items a viewer is no longer allowed to see','It is optional'],a:1,why:'Privacy must be enforced at read time.',hint:'Audience changes.'}],
  terms:[['Social graph','Users and relationships as nodes and edges.'],['Association','An edge such as "likes" or "friend of".'],['Candidate generation','Selecting possible feed items before ranking.']],
  deep:[{h:'Data model',ul:['Objects: user, post, comment, page (id, type, data).','Associations: (id1, type, id2, time) such as friend, likes, authored.','Sharded by object id; associations stored with id1.']},
   {h:'Feed',ul:['Candidates from friends, groups and pages over recent time.','Ranking with features (affinity, recency, engagement predictions).','Cache feed results briefly; paginate.']},
   {h:'Caching and consistency',ul:['Read-through graph cache; write-through invalidation.','Leader and follower cache tiers across regions.','Read-your-writes for the author.']},
   {h:'Scale',ul:['Multi-region replication; writes to the leader region per shard.','Hot objects (celebrity posts) replicated in cache.','Asynchronous counters.']}],
  iq:[{q:'Design friendships and the friend list API.',lvl:'Mid',cover:['Bidirectional edges, pending requests.','Storage and indexes.','Pagination and counts.'],pitfalls:['One row per friendship with no efficient reverse lookup.']},
   {q:'Design the news feed for 2 billion users.',cover:['Candidate generation, ranking, caching.','Fan-out trade-offs.','Privacy filtering.','Latency budget.'],pitfalls:['Chronological pull from all friends without caching.']},
   {q:'How would you keep a global graph cache consistent across regions?',lvl:'Staff+',cover:['Leader region per shard; follower caches invalidated asynchronously.','Read-your-writes by routing the writer\'s reads.','Version numbers to prevent stale refills.','Monitoring staleness.'],pitfalls:['Synchronous cross-region invalidation on every write.']}]});

P(11,{key:'Design Twitter',short:'Twitter',
  lead:'Design Twitter (X): post short tweets, follow users, read a home timeline, search, and see trends. An Amazon SDE-2 report asked for consistent tweet writes with high availability, consistent tweet ids, and a follow-up to support 5 MB videos.',
  more:['Tweets are small and written far less than read. The home timeline uses hybrid fan-out: tweets of normal users are pushed into followers\' timeline caches; tweets of accounts with millions of followers are merged at read time. Tweet ids come from Snowflake. Search uses an inverted index updated in near real time; trends come from streaming counts of hashtags over sliding windows. Media (including the 5 MB video follow-up) is uploaded to object storage, transcoded asynchronously and served via CDN.'],
  clarify:[['Features?','Tweet, follow, home timeline, user timeline, search, trends.'],['Scale?','Assume 300 million daily users, 500 million tweets a day.'],['Timeline consistency?','A few seconds of delay is acceptable; your own tweet must appear immediately.'],['Media?','Images and videos up to 5 MB, as a follow-up.']],
  est:{dau:300e6,writes:1.7,ratio:200,size:300,years:5,peak:3,wlabel:'tweets',rlabel:'timeline reads',unit:'tweet'},
  build:B(['Tweet store sharded by tweet id (Snowflake ids) | High availability and unique, time-ordered ids.','Follower graph store | Who follows whom, both directions.','Fan-out service into timeline caches (Redis lists) | Fast home timelines.','Read-time merge for celebrity tweets | Avoid write storms.','Search index updated from a stream | Real-time search.','Streaming trend detection | Hashtag counts over windows.'],['Building every home timeline by querying all followees on each read | Slow at this read rate.','Auto-increment tweet ids from one database | Bottleneck.','Uploading videos through tweet API servers | Large payloads belong in object storage.']),
  takeaway:'Snowflake ids, sharded tweet storage, hybrid fan-out timelines in caches, streaming search and trends, and media out of band.',
  pre:['Push vs Pull Architecture','Design a Unique ID Generator','Batch vs Stream Processing'],
  quiz:[{q:'Why add the user\'s own tweet to their timeline directly on write?',o:['To save storage','Read-your-writes: users expect to see their own tweet immediately even if fan-out lags','It is required by law'],a:1,why:'Fan-out is asynchronous; the author should not see a delay.',hint:'Whose expectation?'},
        {q:'How would you support a 5 MB video in a tweet?',o:['Store it in the tweet row','Upload to object storage via a pre-signed URL, transcode asynchronously, reference it from the tweet and serve via CDN','Send it over WebSocket'],a:1,why:'Media pipelines keep the tweet path fast.',hint:'Out of band.'}],
  terms:[['Home timeline','Tweets from accounts you follow.'],['User timeline','Tweets by one user.'],['Trend','Topic with unusual growth in mentions.']],
  deep:[{h:'Write path',ul:['Validate; assign Snowflake id; store tweet (replicated).','Publish TweetCreated; fan-out workers push id to followers\' timeline caches.','Skip push for high-follower accounts.']},
   {h:'Read path',ul:['Read timeline cache (list of ids); merge celebrity tweets.','Hydrate tweets from cache; rank or sort.','Cache misses rebuild from follow graph.']},
   {h:'Search and trends',ul:['Inverted index sharded by time and term.','Stream processing counts hashtags in sliding windows, compares to baselines.','Spam filtering.']},
   {h:'Media follow-up',ul:['Upload session API; pre-signed URLs; resumable uploads.','Transcoding queue; multiple resolutions.','Tweet references media id; CDN serving.']}],
  iq:[{q:'Design posting a tweet and reading the home timeline.',lvl:'Mid',cover:['Write and read paths.','Fan-out choice.','Data model.'],pitfalls:['No plan for celebrities.']},
   {q:'Ensure tweet ids are unique, time-ordered and highly available across data centers.',cover:['Snowflake with data center and machine bits.','Machine id management; clock handling.','No central bottleneck.'],pitfalls:['A central counter.']},
   {q:'Design real-time trending topics for 500 million tweets a day.',lvl:'Staff+',cover:['Streaming counts per term per window; heavy hitters (Count-Min sketch).','Compare to historical baselines; regional trends.','Spam and manipulation filtering.','Latency and correctness trade-offs.'],pitfalls:['Counting raw totals without baselines.']}]});

P(11,{key:'Design Reddit',short:'Reddit',
  lead:'Design Reddit: communities (subreddits), posts, nested comments, votes, and ranked feeds such as Hot and Top. A Reddit senior interview reported asking for the feed for a high-traffic subreddit.',
  more:['Votes drive ranking: the Hot score combines votes with age, so rankings change continuously. Recomputing scores per request is too slow; instead, vote counts are updated asynchronously (votes are queued), and ranked lists per subreddit are maintained in caches (sorted sets) and refreshed incrementally. Nested comment trees need efficient storage and loading (load top-level comments with limited depth, then expand). The front page merges ranked lists from subscribed communities.'],
  clarify:[['Feeds?','Subreddit Hot, New, Top; personalised front page.'],['Scale?','Assume 100 million daily users; popular subreddits with millions of members.'],['Vote consistency?','Counts can lag seconds; one vote per user per item.'],['Comments?','Nested, sortable.']],
  est:{dau:100e6,writes:5,ratio:50,size:1000,years:5,peak:3,wlabel:'posts, comments and votes',rlabel:'reads',unit:'item'},
  build:B(['Posts and comments stores partitioned by subreddit and post | Scale writes and keep locality.','Vote service with per-user uniqueness and async counters | Accurate one-vote rule, fast counts.','Ranked list cache per subreddit and sort (sorted sets) | Serve Hot and Top quickly.','Background rankers updating scores | Hot scores change with time.','Comment tree loading with depth limits and pagination | Huge threads.','CDN and caching for anonymous traffic | Most viewers are logged out.'],['Computing Hot scores over all posts on every request | Too slow.','A single counter row per popular post updated synchronously | Hot-key contention.','Loading entire 50,000-comment trees at once | Slow and wasteful.']),
  takeaway:'Queue votes and update counters asynchronously, keep ranked lists per community in caches, refresh time-decaying scores in the background, and load comment trees lazily.',
  pre:['Design Twitter','Caching Strategies','Message Queues'],
  quiz:[{q:'Why are votes processed asynchronously?',o:['To lose some votes','To absorb huge vote bursts and avoid hot-key contention, updating counts shortly after','Votes are not important'],a:1,why:'The user\'s own vote is recorded at once; aggregate counts can lag.',hint:'Bursts on viral posts.'},
        {q:'How do you show the Hot list without recomputing over all posts?',o:['Sort the database each time','Maintain a cached ranked set per subreddit updated as scores change','Show New instead'],a:1,why:'Incremental updates keep reads cheap.',hint:'Precompute.'}],
  terms:[['Hot score','Ranking combining votes and age.'],['Comment tree','Nested replies forming a tree.'],['Materialized path','Storing a node\'s ancestry as a path string.']],
  deep:[{h:'Data model',ul:['subreddits, posts(id, subreddit, author, score, created).','comments(id, post_id, parent_id, path, score).','votes(user, item, value) with a unique key.']},
   {h:'Voting',ul:['Write vote row (upsert); enqueue score change.','Workers aggregate deltas and update counters and ranks.','Anti-manipulation: rate limits, fraud scoring, vote fuzzing.']},
   {h:'Feeds',ul:['Sorted sets per subreddit per sort; capped length.','Front page: merge top items from subscribed subreddits, cache per user briefly.','Anonymous front page cached at the CDN.']},
   {h:'Comments',ul:['Store with parent id and path for ordering.','Load top-N per level; "load more" for the rest.','Cache rendered threads for hot posts.']}],
  iq:[{q:'Design posts, comments and votes with their data model.',lvl:'Mid',cover:['Tables and keys.','One vote per user.','Comment nesting.'],pitfalls:['Votes as a single counter only.']},
   {q:'Design the Hot feed for a subreddit with millions of members during a big event.',cover:['Async vote processing; incremental score updates.','Cached ranked lists; refresh cadence.','CDN for anonymous viewers; hot-post caching.'],pitfalls:['Sorting in the database per request.']},
   {q:'Design the personalised front page for 100 million users.',lvl:'Staff+',cover:['Candidate generation from subscriptions; precomputed top lists per subreddit.','Merge and rank; per-user caching; inactive users on demand.','Diversity and freshness; cost of personalisation.'],pitfalls:['Computing from scratch on every request.']}]});

P(11,{key:'Design Netflix',short:'Netflix',
  lead:'Design a video streaming service: ingest films, transcode them, deliver video worldwide at high quality, and recommend what to watch. Netflix delivers most traffic from its own CDN boxes placed inside internet providers.',
  more:['Each title is transcoded into many resolutions and bitrates and split into segments (adaptive bitrate streaming with DASH or HLS). Segments are pushed to CDN caches near users ahead of demand (Netflix\'s Open Connect appliances sit inside ISPs and are filled overnight). The control plane (catalogue, accounts, licensing, playback authorisation, recommendations) runs on microservices in the cloud; the data plane (video bytes) runs on the CDN. Playback picks the best server and adapts quality to network conditions.'],
  clarify:[['Live or on demand?','On demand.'],['Scale?','Assume 200 million members, peak tens of Tbit/s.'],['Devices?','TVs, phones, browsers with different codecs.'],['Recommendations?','Outline the pipeline.']],
  est:{dau:100e6,writes:0.0001,ratio:20000,size:3e9,years:0,peak:3,wlabel:'new titles',rlabel:'plays',unit:'title (all encodings)'},
  build:B(['Transcoding pipeline into many bitrates and segments | Adaptive quality for every device and network.','Object storage for masters and encodes | Durable source of truth.','CDN appliances near users, filled before peak | Serve the huge byte volume locally.','Playback service choosing the best CDN server and issuing licences | Authorisation and steering.','Adaptive bitrate client (DASH/HLS) | Smooth playback on varying networks.','Recommendation pipeline from viewing events | Personalised home screen.'],['Streaming from a central data center | Bandwidth and latency would be enormous.','Transcoding on demand per play | Expensive and slow; do it ahead.','One monolith for control and data planes | Different scaling needs.']),
  takeaway:'Transcode ahead into many renditions, pre-position segments on CDN caches near users, keep a cloud control plane for authorisation and recommendations, and let clients adapt bitrate.',
  pre:['Content Delivery Network (CDN)','Microservices Architecture'],
  quiz:[{q:'Why pre-position content on CDN servers inside ISPs?',o:['For DRM','So the vast majority of bytes travel a short distance and avoid internet backbones at peak','To transcode faster'],a:1,why:'Popular titles are served locally; filling happens off-peak.',hint:'Where are the bytes?'},
        {q:'What does adaptive bitrate streaming do?',o:['Compresses audio','Lets the client switch between quality levels segment by segment as bandwidth changes','Encrypts video'],a:1,why:'Avoids buffering when the network slows.',hint:'Quality follows bandwidth.'}],
  terms:[['Rendition','One encoding of a title at a given resolution and bitrate.'],['Manifest','File listing segments and renditions.'],['Open Connect','Netflix\'s own CDN.']],
  deep:[{h:'Ingestion and transcoding',ul:['Upload masters; split into chunks; transcode in parallel on many workers.','Per-title encoding ladders optimise quality per bitrate.','Quality checks; DRM packaging.']},
   {h:'Delivery',ul:['Predict popularity; fill CDN caches nightly.','Playback API returns manifests and ranked server URLs.','Client measures throughput and switches renditions.']},
   {h:'Control plane',ul:['Microservices for accounts, catalogue, billing, licences.','Resilience: circuit breakers, fallbacks (default rows on the home screen).','Chaos engineering to test failure.']},
   {h:'Personalisation',ul:['Viewing events to a data pipeline.','Offline models; online ranking of rows and artwork.','A/B testing infrastructure.']}],
  iq:[{q:'Walk through what happens when a user presses play.',lvl:'Mid',cover:['Authorisation, licence, manifest, CDN selection.','Segment fetches and adaptation.','Telemetry.'],pitfalls:['Streaming from app servers.']},
   {q:'Design the transcoding pipeline for 1,000 new titles a week.',cover:['Chunked parallel transcoding; queues and workers.','Multiple codecs and ladders; QC; DRM.','Storage and cost estimates.'],pitfalls:['Transcoding whole files on one machine.']},
   {q:'A new season of a hit show launches globally at the same minute. Prepare the system.',lvl:'Staff+',cover:['Pre-position all renditions on CDN caches.','Scale control plane; pre-warm caches; rate-limit non-critical calls.','Fallbacks and load shedding; regional failover.','Monitoring and war room.'],pitfalls:['Relying on cache misses at launch.']}]});

P(11,{key:'Design Youtube',short:'YouTube',
  lead:'Design YouTube: anyone uploads videos, which are processed and streamed to billions of viewers, with search, comments, view counts and recommendations. Unlike Netflix, uploads come from everyone at huge volume, and most videos are rarely watched.',
  more:['Uploads go through resumable uploads to object storage, then a processing DAG: transcode into renditions, generate thumbnails, run content checks. Popular videos are served from CDN caches; the long tail is served from origin or regional caches. View counts are high-volume writes handled with aggregation (sharded counters, streaming). Metadata and search scale with sharded databases and search indexes.'],
  clarify:[['Upload volume?','Assume 500 hours of video uploaded per minute.'],['Views?','Billions per day.'],['Live streaming?','Out of scope.'],['Monetisation?','Out of scope.']],
  est:{dau:1e9,writes:0.001,ratio:5000,size:500e6,years:5,peak:3,wlabel:'uploads',rlabel:'views',unit:'video (all renditions)'},
  build:B(['Resumable upload service to object storage | Large files over flaky connections.','Processing DAG: transcode, thumbnails, moderation | Prepare videos for every device.','CDN for popular videos, origin for the long tail | Cost-effective delivery.','Metadata DB and search index | Discovery.','View count aggregation via streaming | Billions of increments.','Recommendation pipeline | Personalised discovery.'],['Synchronous transcoding during upload | Takes minutes to hours.','Incrementing one database row per view | Hot-key contention.','Caching every video at every edge | Long tail makes that wasteful.']),
  takeaway:'Resumable uploads, an async processing DAG, CDN for the popular head and origin for the long tail, aggregated counters, and separate pipelines for search and recommendations.',
  pre:['Design Netflix','Message Queues','Distributed Caching'],
  quiz:[{q:'Why not cache every video on every CDN edge?',o:['CDNs forbid it','Most videos are rarely watched, so storing them everywhere wastes capacity','It is slower'],a:1,why:'Cache the popular head; serve the long tail from fewer places.',hint:'Popularity is skewed.'},
        {q:'How do you count billions of views without overloading the database?',o:['One row per video incremented per view','Aggregate views in streams or sharded counters and write totals periodically','Skip counting'],a:1,why:'Batching and sharding remove hot-key contention.',hint:'Hot keys.'}],
  terms:[['Resumable upload','Upload that can continue after interruption.'],['Processing DAG','Graph of processing tasks per upload.'],['Long tail','The many videos with few views.']],
  deep:[{h:'Upload',ul:['Create upload session; chunked resumable transfer.','Store original; emit event to processing.','Status visible to the uploader.']},
   {h:'Processing',ul:['Split into segments; parallel transcode to renditions and codecs.','Thumbnails, captions, content ID matching, safety checks.','Publish when ready.']},
   {h:'Serving',ul:['Manifest with renditions; ABR on client.','CDN caching by popularity; regional caches.','Signed URLs.']},
   {h:'Engagement data',ul:['View events streamed; deduplicated; aggregated per video.','Comments sharded by video.','Recommendations from watch history.']}],
  iq:[{q:'Design video upload and processing.',lvl:'Mid',cover:['Resumable upload; storage; queue; workers.','Transcoding ladder; thumbnails.','Status and failure retries.'],pitfalls:['Doing it synchronously.']},
   {q:'Design view counting that is accurate enough for creators and resistant to fraud.',cover:['Event pipeline; dedup per session; bot filtering.','Near-real-time approximate counts; periodic exact recount.','Sharded counters.'],pitfalls:['Counting every page load.']},
   {q:'Estimate storage and bandwidth for YouTube and decide where to cut costs.',lvl:'Staff+',cover:['500 hours per minute x renditions x bitrate = petabytes per day.','Bandwidth dominated by popular videos via CDN.','Cost levers: codec efficiency (AV1), fewer renditions for the long tail, cold storage tiers.'],pitfalls:['No numbers.']}]});

P(11,{key:'Design Google Search',short:'Google Search',
  lead:'Design a web search engine: crawl the web, build an index, and answer queries with ranked results in a few hundred milliseconds.',
  more:['The offline side crawls pages, extracts text and links, computes signals such as PageRank, and builds an inverted index (term to list of documents) sharded across many machines. The online side parses a query, sends it to all index shards in parallel (each returns its local top results), merges and re-ranks them, and builds snippets. Tail latency across thousands of shards, index freshness, and caching of popular queries are the key deep dives.'],
  clarify:[['Scope?','Web pages only; no images or ads.'],['Index size?','Tens of billions of pages.'],['Latency?','Under 300 ms.'],['Freshness?','News within minutes, most pages within days.']],
  est:{dau:1e9,writes:4,ratio:1,size:20000,years:0,peak:3,wlabel:'searches',rlabel:'index shard queries (per search, fanned out)',unit:'query log'},
  build:B(['Web crawler with URL frontier | Collect pages.','Indexing pipeline building a sharded inverted index | Map terms to documents.','Link analysis (PageRank) and ranking signals | Quality ordering.','Query service fanning out to shards and merging top-k | Parallel search.','Result cache for popular queries | Cut work for repeated queries.','Fresh index tier for recent content | News and fast-changing pages.'],['Scanning all documents per query | Impossible.','A single relational database with LIKE queries | Far too slow.','Waiting for the slowest of thousands of shards without timeouts | Tail latency.']),
  takeaway:'Crawl, build a sharded inverted index with ranking signals offline, and answer queries by fanning out to shards, merging top results and caching popular queries, with care for tail latency.',
  pre:['Design Distributed Web Crawler','Latency vs Throughput','Database Partitioning'],
  quiz:[{q:'What is an inverted index?',o:['A reversed list of URLs','A map from each term to the documents that contain it','A backup index'],a:1,why:'It lets the engine find matching documents without scanning them all.',hint:'Term to documents.'},
        {q:'How do you control latency when one query hits 1,000 shards?',o:['Wait for all','Set deadlines, use replicas and hedged requests, and return results from shards that answered','Use one shard'],a:1,why:'Tail latency grows with fan-out.',hint:'Slowest shard problem.'}],
  terms:[['Inverted index','Term to posting list of documents.'],['Posting list','Documents (and positions) for one term.'],['PageRank','Link-based importance score.']],
  deep:[{h:'Indexing',ul:['Parse, tokenise, normalise text.','Build posting lists with positions; compress.','Shard by document; replicas per shard.']},
   {h:'Ranking',ul:['Text relevance (BM25), PageRank, freshness, user signals.','Two stages: cheap retrieval, expensive re-ranking of top candidates.','Machine-learned ranking models.']},
   {h:'Query serving',ul:['Spell correction, query understanding.','Fan-out to shards with deadlines; merge top-k.','Snippet generation; result caching.']},
   {h:'Freshness',ul:['Separate fast index for new content merged at query time.','Recrawl frequency by change rate and importance.','Incremental index updates.']}],
  iq:[{q:'Explain inverted indexes and how a query is answered.',lvl:'Mid',cover:['Posting lists, intersections, scoring.','Top-k selection.'],pitfalls:['Scanning documents.']},
   {q:'Design query serving with a 200 ms budget over a sharded index.',cover:['Fan-out, deadlines, hedging, partial results.','Caching; two-stage ranking.','Capacity planning.'],pitfalls:['Ignoring tail latency.']},
   {q:'Design index freshness so breaking news is searchable within 2 minutes.',lvl:'Staff+',cover:['Priority crawling of news sources; feeds and sitemaps.','Real-time index tier merged at query time.','Ranking freshness signals; spam defence.'],pitfalls:['Rebuilding the whole index faster.']}]});
